rengyl Garroso", desc="Usa el Polvo lunar Cenarion en la piedra de lechúcico lunar de Auberdine, derrota a Garraluna y habla con su espíritu. Al terminar Costa Oscura, vuelve a Darnassus para entregarla y aprender Forma de oso."}, [151]={npc="Syurna", tgt="Syurna", desc="Acéptala en Dolanaar y entrégala a Syurna en Darnassus."}, [152]={npc="Syurna", tgt="Syurna"}, [153]={hint="Encuentra a Sethir el Ancestro y ve a contarle todo lo que descubras a Syurna."}, [154]={npc="Syurna", tgt="Syurna"}, [155]={npc="Sacerdotisa Alathea", tgt="Sacerdotisa Alathea", desc="Acéptala en Dolanaar y entrégala a la Sacerdotisa Alathea en Darnassus."}, [156]={npc="Sacerdotisa Alathea", tgt="Sacerdotisa Alathea", desc="Después, aprende Astillas de estrellas."}, [157]={npc="Sacerdotisa Alathea", tgt="Sacerdotisa Alathea", desc="Después, aprende Astillas de estrellas."}, [158]={npc="Astaia", tgt="Astaia", tag="Opcional"}, [159]={npc="Trianna", tgt="Trianna", tag="Opcional"}, [160]={text="Cruza el portal de Darnassus hasta Aldea Rut'theran."}, [161]={npc="Nessa Cantosombrío", tgt="Nessa Cantosombrío"}, [162]={npc="Nessa Cantosombrío", tgt="Nessa Cantosombrío"}, [163]={npc="Vesprystus", tgt="Vesprystus"}, [164]={nodeA="{a:702}", node="Rut'theran Village"}, [165]={npc="Vesprystus", tgt="Vesprystus"}, [166]={to="Auberdine", desc="Si Auberdine no está en tu mapa de vuelos, toma el barco en el muelle de Aldea Rut'theran hasta Auberdine."}, [167]={npc="Laird", tgt="Laird"}, [168]={npc="Laird", tgt="Laird"}, [169]={npc="Elisa Mano de Acero", tgt="Elisa Mano de Acero", tag="Opcional"}, [170]={npc="Jenna Lemkenilli", tgt="Jenna Lemkenilli", tag="Opcional"}, [171]={npc="Kurdram Rocamartillo", tgt="Kurdram Rocamartillo", tag="Opcional"}, [172]={to="Stormwind", from="Auberdine"}, [173]={text="Vincula tu piedra de hogar en la posada de Ciudad de Ventormenta (60.50, 75.20)."}, [174]={node="Stormwind"}, [175]={npc="Grimand Elmore", tgt="Grimand Elmore"}, [176]={text="Ve al Distrito de los Enanos de Ventormenta y toma el Tranvía Subterráneo a Forjaz."}, [177]={node="Forjaz"}}},
    ["01-7"] = {tips={{k="交通", text="Zona de inicio de los Skyborne. La Alianza y la Horda comparten las misiones iniciales de la isla y solo se separan por facción al salir de ella.", s={{"Zona de inicio de los Skyborne. La Alianza y la Horda comparten las misiones iniciales de la isla y solo se separan por facción al salir de ella.", {race={"Skyborne"}}}}}}, grind={[1]={mob="Mosca de cirro soldado", note="El enjambre del lado este de la Arboleda Thendal; hay muchas y te pilla de paso para matar a la reina."}, [2]={mob="Ursera escuálido", note="El bosque al oeste de la torre de vigilancia; enemigos normales que puedes atraer de uno en uno."}}, steps={[1]={npc="Dalia la Coleccionista", tgt="Ailee Corazón Lejano"}, [2]={npc="Ailee Corazón Lejano", tgt="Rorian el Buscadía"}, [3]={npc="Ailee Corazón Lejano", tgt="Rorian el Buscadía"}, [4]={npc="Falorne Trombaviento", tgt="Elatrell Plumaligera"}, [5]={hint="Mata a 8 vuldren juveniles en la Arboleda Thendal."}, [6]={hint="Mata a 8 moscas de cirro molestas en la Arboleda Thendal."}, [7]={npc="Falorne Trombaviento", tgt="Elatrell Plumaligera"}, [8]={npc="Falorne Trombaviento", tgt="Elatrell Plumaligera"}, [9]={npc="Halaan Ojo de Halcón", tgt="Halaan Ojo de Halcón"}, [10]={npc="Halaan Ojo de Halcón", tgt="Halaan Ojo de Halcón"}, [11]={npc="Myriaal Brumapaso", tgt="Myriaal Brumapaso"}, [12]={hint="Salta desde lo alto de la torre de la Arboleda Thendal y utiliza tu facultad Caminar sobre el aire para frenar tu caída.", desc="Usa tu habilidad racial Skyborne al saltar hacia la Reina mosca de cirro."}, [13]={desc="Si aún no eres nivel 3, sube hasta el 3 matando moscas de cirro soldado y urseras escuálidos en la Arboleda Thendal, al pie de la torre."}, [14]={hint="Destruye a la reina mosca de cirro en la Arboleda Thendal."}, [15]={npc="Falorne Trombaviento", tgt="Elatrell Plumaligera"}, [16]={npc="Ailee Corazón Lejano", tgt="Rorian el Buscadía"}, [17]={npc="Ailee Corazón Lejano", tgt="Rorian el Buscadía"}, [18]={npc="Ailee Coraz