    ["01-9"] = {tips={{k="交通", text="Desde Ventormenta, toma el Tranvía Subterráneo hacia Forjaz. Si saliste pronto de Teldrassil, toma primero el barco de Auberdine a Ventormenta y luego el tranvía."}}, steps={[1]={npc="Rudra Calmámbar", tgt="Rudra Calmámbar", tag="Opcional, Grupo recomendado"}, [2]={hint="Rudra Cieloámbar quiere que mates a Vagash y que le lleves su colmillo al rancho de carneros.", tag="Opcional, Grupo recomendado"}, [3]={npc="Rudra Calmámbar", tgt="Rudra Calmámbar", tag="Opcional, Grupo recomendado"}, [4]={npc="Videnterra Farsen", tgt="Videnterra Farsen"}, [5]={npc="Videnterra Farsen", tgt="Videnterra Farsen"}, [6]={npc="Videnterra Farsen", tgt="Videnterra Farsen"}, [7]={npc="Senador Mehr Piedrasanta", tgt="Senador Mehr Piedrasanta"}, [8]={npc="Supervisor Petrocejas", tgt="Supervisor Petrocejas"}, [9]={hint="Mata a 10 espías Hierro Negro en Dun Morogh."}, [10]={npc="Mapa Hierro Negro", npcObj=true, desc="Haz clic derecho en Mapa Hierro Negro en tu bolsa para empezar la misión."}, [11]={hint="Mata a 6 aplastacráneos Comepiedras para Foreman Petrocejas de la Cantera de Gol'Bolar."}, [12]={hint="Mata a 10 quebrantahuesos Comepiedras para el senador Mehr Piedrasanta de la Cantera de Gol'Bolar."}, [13]={npc="Supervisor Petrocejas", tgt="Supervisor Petrocejas"}, [14]={npc="Senador Mehr Piedrasanta", tgt="Senador Mehr Piedrasanta"}, [15]={npc="Videnterra Farsen", tgt="Videnterra Farsen"}, [16]={npc="Videnterra Farsen", tgt="Videnterra Farsen"}, [17]={npc="Piloto Podomartillo", tgt="Piloto Podomartillo"}, [18]={npc="Un cadáver de enano", npcObj=true}, [19]={npc="Un cadáver de enano", npcObj=true}, [20]={hint="Mata a Zarpasarnosa."}, [21]={npc="Piloto Podomartillo", tgt="Piloto Podomartillo"}, [22]={text="Hay que cruzar la montaña: en lugar del túnel de la Puerta Norte, sube por la ladera hacia el este y sigue la flecha por la cresta hasta el otro lado (79.40, 49.90 → 80.40, 49.70 → 81.50, 50.10 → 83.10, 49.50); luego salta primero a la plataforma de del