    ["02-10"] = {steps={[1]={npc="Maniveo Zumbang", tgt="Maniveo Zumbang"}, [2]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [3]={node="Auberdine"}, [4]={hint="Reúne 6 piernas de reptador y colócalas en la caja mecánica 827.", desc="Recoge patas de los cangrejos de nivel 9-10 en la costa al sur de Auberdine. Si aún no tienes la misión de la criatura varada, acéptala la próxima vez que pases por el muelle a partir del nivel 11."}, [5]={hint="Recoge huesos de la criatura marina varada que está al sur de Auberdine y llévaselos a Gwennyth Bly'Leggonde a Auberdine."}, [6]={npc="Caja mecánica 827", npcObj=true}, [7]={npc="Caja mecánica 827", npcObj=true}, [8]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [9]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [10]={hint="Lleva 8 piezas de mineral de elunita y el Medallón de Elura a Elanaria en Darnassus."}, [11]={npc="Cerellean Zarpablanca", tgt="Cerellean Zarpablanca"}, [12]={hint="Recoge restos de la tortuga marina esquelética de las aguas del oeste de Auberdine y vuelve a Auberdine a hablar con Gwennyth Bly'Leggonde."}, [13]={hint="Consigue 3 ojos de trillador de los trilladores de Costa Oscura en las profundidades del mar, cerca de la caja mecánica 411."}, [14]={npc="Thundris Tejevientos", tgt="Thundris Tejevientos"}, [15]={npc="Thundris Tejevientos", tgt="Thundris Tejevientos"}, [16]={npc="Tharnariun Espinarbolado", tgt="Tharnariun Espinarbolado"}, [17]={npc="Terenthis", tgt="Terenthis"}, [18]={hint="Captura un Oso Cardo rabioso vivo y llévaselo a Tharnariun."}, [19]={hint="Utiliza el polvo de luna Cenarion en la piedra de lechúcico lunar de Auberdine para invocar a Garraluna. Luego tendrás que enfrentarte a Garraluna y ganar la fuerza física y de corazón que posee."}, [20]={npc="Asterion", tgt="Asterion"}, [21]={npc="Asterion", tgt="Asterion"}, [22]={hint="Consigue 8 pendientes de grell y llévaselos a Asterion a Bashal'Aran."}, [23]={npc="Asterion", tgt="Asterion"}, [24]={npc="Asterion", tgt="Asterion"}, [25]={hint="Consigue el lacre de piedra lunar antiguo y llévaselo a Asterion a Bashal'Aran."}, [26]={npc="Asterion", tgt="Asterion"}, [27]={npc="Asterion", tgt="Asterion"}, [28]={npc="Tharnariun Espinarbolado", tgt="Tharnariun Espinarbolado"}, [29]={npc="Tharnariun Espinarbolado", tgt="Tharnariun Espinarbolado"}, [30]={npc="Centinela Glynda Nal'Shea", tgt="Centinela Glynda Nal'Shea"}, [31]={npc="Barithras Sombraluna", tgt="Barithras Sombraluna"}, [32]={npc="¡Se busca: Viscoso!", npcObj=true}, [33]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [34]={hint="Viaja al este de Auberdine y busca un gran cristal rojo en la zona montañosa que hay al este de Costa Oscura. Vuelve a Auberdine e informa de lo que has encontrado a la centinela Glynda Nal'Shea."}, [35]={npc="Centinela Tysha Filoluna", tgt="Centinela Tysha Filoluna"}, [36]={hint="Estudia las tablillas que hablan de Ameth'Aran y de su caída y reúnete con la centinela Tysha Filoluna en Costa Oscura."}, [37]={hint="Libera el espíritu de Anaia Correalba y lleva su colgante a Cerellean Zarpablanca a Auberdine."}, [38]={hint="Reúne 7 reliquias de los altonatos y llévaselas a Thundris Tejevientos a Auberdine."}, [39]={hint="Destruye el lacre de piedra lunar antiguo en la antigua llama de Ameth'Aran y vuelve a reunirte con Asterion en Bashal'Aran."}, [40]={hint="Encuentra y mata al búho conocido como Jai'vhanel y llévate una de sus plumas. Lo vieron por última vez al norte de las ruinas de Ameth'Aran, cerca del pie de la montaña. Informa de la muerte de Jai'vhanel a la centinela Glynda Nal'Shea en Auberdine."}, [41]={npc="Centinela Tysha Filoluna", tgt="Centinela Tysha Filoluna"}, [42]={npc="Tortuga marina varada", npcObj=true, desc="Ve al sur y mata más Osos Cardo rabiosos, también por 38, 60. Para al llegar a 6-10."}, [43]={hint="Encuentra el campamento de furbolgs corruptos en Costa Oscura, vuelve a Auberdine y busca a Terenthis."}, [44]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth