    ["02-17"] = {steps={[1]={to="Lakeshire", toA="{a:69}", tag="Aún no tienes esta ruta de vuelo. Ve a pie la primera vez.", desc="Si ya tienes el punto de vuelo de Villa Oscura, vuela directo a Villa Oscura. Si no, vuela a Villa del Lago, sigue el camino al oeste hasta el cruce del extremo oeste de Montañas Crestagrana y ve al sur por el Bosque del Ocaso hasta Villa Oscura."}, [2]={npc="Lady Eva", tgt="Lady Eva", desc="Al cruzar el Bosque del Ocaso, mata arañas para conseguir Patas de araña babosas."}, [3]={npc="Lady Eva", tgt="Lady Eva"}, [4]={npc="Dependiente Daltry", tgt="Dependiente Daltry"}, [5]={npc="Dependiente Daltry", tgt="Dependiente Daltry"}, [6]={npc="Sirra Von'Indi", tgt="Sirra Von'Indi"}, [7]={npc="Comandante Althea Cerranegro", tgt="Comandante Althea Cerranegro"}, [8]={npc="Elaine Carevin", tgt="Elaine Carevin"}, [9]={npc="Elaine Carevin", tgt="Elaine Carevin"}, [10]={npc="Elaine Carevin", tgt="Elaine Carevin"}, [11]={nodeA="{a:42}", node="Darkshire"}, [12]={text="Tubo de bronce", desc="Existencias limitadas. Cómpralo solo si está disponible y aún no lo tienes."}, [13]={npc="Viktori Prism'Antras", tgt="Viktori Prism'Antras", desc="La cadena de observar las estrellas necesita un Tubo de bronce para empezar. Si no tienes, haz primero lo demás y cómpralo luego en la casa de subastas."}, [14]={npc="Arco de Merrick", npcObj=true, tag="Opcional", desc="Haz clic derecho en Arco de Merrick en tu bolsa para empezar la misión."}, [15]={npc="Bath'rah el Vigía del viento", tgt="Bath'rah el Vigía del viento", npcObj=true, tag="Opcional", desc="Haz clic derecho en la Daga de Ira de tu mochila para aceptar la misión."}, [16]={npc="Viktori Prism'Antras", tgt="Viktori Prism'Antras"}, [17]={npc="Viktori Prism'Antras", tgt="Viktori Prism'Antras"}, [18]={npc="Mary la Ciega", tgt="Mary la Ciega"}, [19]={npc="Mary la Ciega", tgt="Mary la Ciega"}, [20]={hint="Quita el espejo de Mary la Ciega al necrófago demente y llévaselo a Viktori a Villa Oscura."}, [21]={hint="La coman