    ["05-d4"] = {name="Las Mazmorras", entrance="Ventormenta 52.41, 70.01", pickup="Acepta «Lo que sucece alrededor…» en Villa del Lago y «Crimen y castigo» en Villa Oscura. Para «El motín de las Mazmorras» debes entregar primero la carta de VanCleef. Si no la tienes, haz las demás misiones. Busca grupo para «La furia mora en las profundidades» después de completar «La guerra contra los Hierro Negro» en Los Humedales.", pickupS={{"Acepta «Lo que sucece alrededor…» en Villa del Lago y «Crimen y castigo» en Villa Oscura"}, {"Para «El motín de las Mazmorras» debes entregar primero la carta de VanCleef"}, {"Si no la tienes, haz las demás misiones"}, {"Busca grupo para «La furia mora en las profundidades» después de completar «La guerra contra los Hierro Negro» en Los Humedales"}}, steps={[1]={npc="Consejero Tallolino", tgt="Consejero Tallolino"}, [2]={text="Requisito previo: Lo que sucece alrededor…"}, [3]={npc="Una carta sin enviar", npcObj=true, tag="Solo si cae", desc="Lo suelta VanCleef en Las Minas de la Muerte: haz clic derecho para aceptar la misión."}, [4]={npc="Baros Alexston", tgt="Baros Alexston"}, [5]={npc="Baros Alexston", tgt="Baros Alexston"}, [6]={npc="Alcaide Thelagua", tgt="Alcaide Thelagua"}, [7]={npc="Alcaide Thelagua", tgt="Alcaide Thelagua"}, [8]={npc="Alcaide Thelagua", tgt="Alcaide Thelagua"}, [9]={npc="Nikova Raskol", tgt="Nikova Raskol"}, [10]={text="Entrada: Las Mazmorras"}, [11]={hint="El alcaide Thelagua de Ventormenta quiere que mates 10 prisioneros Defias, 8 presidiarios Defias y 8 insurgentes Defias en las Mazmorras."}, [12]={hint="Mata a Bazil Thredd y lleva su cabeza al alcaide Thelagua en las Mazmorras."}, [13]={hint="Nikova Raskol, de Ventormenta, quiere que consigas 10 pañuelos de lana roja."}, [14]={hint="El consejero Tallolino de Villa Oscura quiere que le lleves la mano de Dextren Tutor."}, [15]={hint="Lleva la cabeza de Targor el Horror al guardia Berton a Villa del Lago.", tag="Grupo recomendado, Opcional"}, [16]={hint="Motley Garmason quiere que le lleves la cabeza de Kam Furiahonda a Dun Modr.", tag="Grupo recomendado, Opcional"}, [17]={npc="Alcaide Thelagua", tgt="Alcaide Thelagua"}, [18]={npc="Alcaide Thelagua", tgt="Alcaide Thelagua"}, [19]={npc="Nikova Raskol", tgt="Nikova Raskol"}, [20]={npc="Guardia Berton", tgt="Guardia Berton", tag="Grupo recomendado, Opcional, Hazlo cuando te pille de paso", desc="Guárdala hasta la {s:02-19} y entrégala al pasar por Villa del Lago."}, [21]={npc="Consejero Tallolino", tgt="Consejero Tallolino", tag="Opcional, Grupo recomendado, Hazlo cuando te pille de paso", desc="Guárdala hasta la {s:03-22} y entrégala al pasar por Villa Oscura."}, [22]={npc="Motley Garmason", tgt="Motley Garmason", tag="Grupo recomendado, Hazlo cuando te pille de paso"}}},
