ua", npcObj=true, desc="Haz clic derecho en Sobre estropeado por el agua en tu bolsa para empezar la misión."}, [64]={hint="Destruye el cajón de explosivos."}, [65]={npc="Rhag Garmason", tgt="Rhag Garmason"}, [66]={npc="Rhag Garmason", tgt="Rhag Garmason"}, [67]={npc="Capitán Nials", tgt="Capitán Nials"}, [68]={nodeA="{a:320}", node="Refuge Pointe"}, [69]={to="Forjaz"}, [70]={npc="Sara Balloo", tgt="Sara Balloo"}, [71]={npc="Sara Balloo", tgt="Sara Balloo"}, [72]={npc="Rey Magni Barbabronce", tgt="Rey Magni Barbabronce"}, [73]={npc="Rey Magni Barbabronce", tgt="Rey Magni Barbabronce"}, [74]={npc="Piloto Barbalarga", tgt="Piloto Barbalarga"}, [75]={npc="Gran mampostero Marmolez", tgt="Gran mampostero Marmolez"}, [76]={npc="Gran mampostero Marmolez", tgt="Gran mampostero Marmolez"}, [77]={npc="Maestro manitas Sobrechispa", tgt="Maestro manitas Sobrechispa"}, [78]={npc="Maestro manitas Sobrechispa", tgt="Maestro manitas Sobrechispa", tag="Grupo recomendado, Opcional", desc="Misión de la mazmorra de Gnomeregan; acéptala solo si vas a hacer Gnomeregan."}, [79]={npc="Manitas mayor Mekkatorque", tgt="Manitas mayor Mekkatorque", tag="Grupo recomendado, Opcional"}, [80]={npc="Maestro mecánico Funditubo", tgt="Maestro mecánico Funditubo", tag="Grupo recomendado, Opcional"}, [81]={to="Menethil Harbor", toA="{a:150}"}, [82]={npc="Capitán Puñorrecio", tgt="Capitán Puñorrecio"}, [83]={npc="Capitán Puñorrecio", tgt="Capitán Puñorrecio"}, [84]={npc="Capitán Puñorrecio", tgt="Capitán Puñorrecio"}, [85]={npc="Capitán Puñorrecio", tgt="Capitán Puñorrecio", tag="Solo si pasas por aquí, Opcional"}, [86]={npc="James Halloran", tgt="James Halloran"}, [87]={npc="James Halloran", tgt="James Halloran"}, [88]={npc="James Halloran", tgt="James Halloran", desc="Entrégasela a Howin Plumamable de camino a las catapultas."}, [89]={npc="Glorin Frenteacerada", tgt="Glorin Frenteacerada"}, [90]={npc="Glorin Frenteacerada", tgt="Glorin Frenteacerada"}, [91]={npc="Howin Plumamable", tgt="Howin Plumamab