    ["05-d7"] = {name="Gnomeregan", entrance="Dun Morogh 24.30, 39.80", pickup="Acepta las misiones de la mazmorra al pasar por Vallefresno (2.ª visita); así no tendrás que volver antes de entrar.", pickupS={{"Acepta las misiones de la mazmorra al pasar por Vallefresno (2.ª visita); así no tendrás que volver antes de entrar"}}, steps={[1]={npc="Gaxim Silvóxido", tgt="Gaxim Silvóxido"}, [2]={npc="Hermano Sarno", tgt="Hermano Sarno"}, [3]={npc="Shoni el Shilenshioso", tgt="Shoni el Shilenshioso", tag="Grupo recomendado, Opcional"}, [4]={npc="Maestro manitas Sobrechispa", tgt="Maestro manitas Sobrechispa", tag="Grupo recomendado, Opcional"}, [5]={npc="Manitas mayor Mekkatorque", tgt="Manitas mayor Mekkatorque", tag="Grupo recomendado, Opcional"}, [6]={npc="Maestro mecánico Funditubo", tgt="Maestro mecánico Funditubo", tag="Grupo recomendado, Opcional"}, [7]={npc="Klockmort Palmalicate", tgt="Klockmort Palmalicate"}, [8]={npc="Gnoarn", tgt="Gnoarn", tag="Opcional, Grupo recomendado"}, [9]={npc="Oci Voltiflop", tgt="Oci Voltiflop"}, [10]={npc="Oci Voltiflop", tgt="Oci Voltiflop", tag="Opcional, Grupo recomendado"}, [11]={npc="Oci Voltiflop", tgt="Oci Voltiflop", tag="Opcional, Grupo recomendado"}, [12]={npc="Mathiel", tgt="Mathiel", tag="Opcional", desc="Acéptala en Darnassus, requiere nivel 24: vuela de Auberdine a Aldea Rut'theran y entra en la ciudad por el portal. Si no quieres dar el rodeo, sáltala junto con la entrega posterior a la mazmorra."}, [13]={text="Vuela de Puerto de Menethil a Forjaz, sal por las puertas de la ciudad y sigue el camino de Dun Morogh hacia el oeste hasta Gnomeregan."}, [14]={text="Entrada: Gnomeregan"}, [15]={hint="Usa la ampolla de plomo con invasores o saqueadores radiactivos para recoger restos radiactivos. Cuando esté llena, llévasela a Ozzie Voltiflop a Kharanos.", tag="Opcional, Grupo recomendado", spot="Puedes repartir la cadena entre varias visitas. Recoge la primera muestra en los túneles de entrada o dentro de la mazmorra. Llévasela a Ozzie en Kharanos para recibir el vial pesado."}, [16]={hint="Viaja hasta Gnomeregan y recupera los restos radiactivos de gran potencia. Pero ten cuidado, ya que es inestable y podría explotar en cualquier momento.", tag="Opcional, Grupo recomendado", spot="Usa el vial pesado con una babosa irradiada, un rondador corrosivo o un horror irradiado. La muestra dura dos horas. Si no puedes volver a Kharanos a tiempo, recógela en tu próxima visita en grupo."}, [17]={hint="Lleva veinticuatro entrañas robomecánicas a Shoni en Ventormenta.", tag="Grupo recomendado, Opcional", desc="Lo sueltan los enemigos mecánicos; entrégala cuando vuelvas a Ventormenta."}, [18]={npc="Anillo con mugre incrustada", npcObj=true, tag="Solo si cae, Opcional"}, [19]={hint="Encuentra la manera de limpiar el anillo sucio.", tag="Opcional", spot="El Destellamatic 5200, en la Zona Limpia. Lleva 3 monedas de plata."}, [20]={npc="La Chispamática 5200", npcObj=true, tag="Opcional"}, [21]={npc="La Chispamática 5200", npcObj=true, tag="Opcional"}, [22]={npc="Kernobee", tgt="Kernobee", tag="Opcional, Grupo recomendado", spot="En el dormitorio junto a la Zona Limpia. Despejad el camino de vuelta a la salida y esperad a todo el grupo antes de hablar con Kernobee."}, [23]={hint="Acompaña a Kernobee a La rampa del engranaje y luego ve a ver a Scooty a Bahía del Botín.", tag="Escolta, Opcional, Grupo recomendado", desc="Entrega la misión a Scooty la primera vez que pases por Bahía del Botín en la Vega de Tuercespina."}, [24]={npc="Oci Voltiflop", tgt="Oci Voltiflop", tag="Opcional, Grupo recomendado"}, [25]={npc="Oci Voltiflop", tgt="Oci Voltiflop", tag="Opcional, Grupo recomendado"}, [26]={npc="Oci Voltiflop", tgt="Oci Voltiflop", tag="Opcional, Grupo recomendado"}, [27]={npc="Maestro manitas Sobrechispa", tgt="Maestro manitas Sobrechispa"}, [28]={npc="Maestro manitas Sobrechispa", tgt="Maestro manitas Sobrechispa", tag="Opcional, Grupo recomendado"}, [29]={npc="Maestro mecánico Funditubo", tgt="Maestro 