    ["03-26"] = {name="Vega de Tuercespina", steps={[1]={npc="Sven Yorgen", tgt="Sven Yorgen"}, [2]={npc="Sven Yorgen", tgt="Sven Yorgen", tag="Opcional, Grupo recomendado"}, [3]={hint="Utiliza la Pesadilla de Morbent contra Morbent Vil, mata a Morbent Vil y luego ve al campamento de Sven y devuélvele la Pesadilla de Morbent.", tag="Opcional, Grupo recomendado", desc="Las siguientes son misiones élite. Hazlas solo en grupo."}, [4]={npc="Sven Yorgen", tgt="Sven Yorgen", tag="Opcional, Grupo recomendado"}, [5]={text="Desde el oeste del Bosque del Ocaso, sigue el camino al sur hasta Vega de Tuercespina y ve primero al Campamento Rebelde."}, [6]={npc="Soldado Thorsen", tgt="Soldado Thorsen", tag="Opcional, hazlo si lo ves", desc="Patrulla por el camino y solo te da la misión si lo salvas cuando le tienden una emboscada; si no te lo encuentras, sáltatela."}, [7]={npc="Sargento Yohwa", tgt="Sargento Yohwa"}, [8]={npc="Sargento Yohwa", tgt="Sargento Yohwa"}, [9]={npc="Teniente Doren", tgt="Teniente Doren", tag="Opcional"}, [10]={npc="Teniente Doren", tgt="Teniente Doren"}, [11]={npc="Barnil Jarropetra", tgt="Barnil Jarropetra"}, [12]={npc="Hemet Decautela", tgt="Hemet Decautela"}, [13]={npc="Hemet Decautela", tgt="Hemet Decautela"}, [14]={npc="Barnil Jarropetra", tgt="Barnil Jarropetra", tag="Opcional", desc="Las páginas caen al azar de los enemigos de Tuercespina. Compra las que falten en la casa de subastas y entrega cuando tengas los cuatro capítulos."}, [15]={npc="Barnil Jarropetra", tgt="Barnil Jarropetra", tag="Opcional"}, [16]={npc="Barnil Jarropetra", tgt="Barnil Jarropetra", tag="Opcional"}, [17]={npc="Barnil Jarropetra", tgt="Barnil Jarropetra", tag="Opcional"}, [18]={npc="Barnil Jarropetra", tgt="Barnil Jarropetra", tag="Opcional"}, [19]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [20]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [21]={hint="Ajeck Rouack de la Expedición de Nesingwary, quiere que mates 10 tigres jóvenes de Tuercespina."}, [22]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [23]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [24]={hint="Sir S. J. Erlgadin de la Expedición de Nesingwary, quiere que mates 10 panteras jóvenes."}, [25]={hint="Ajeck Rouack de la Expedición de Nesingwary, quiere que mates 10 tigres de Tuercespina."}, [26]={hint="Mata 15 combatientes de la jungla Kurzen."}, [27]={hint="Lleva 7 remedios de la jungla y 1 extracto de veneno de helecho al sargento Yohwa en el Asentamiento Rebelde."}, [28]={npc="Documentos de Bookie Herod", npcObj=true, desc="Los archivos que hay en la Base de Kurzen; la continuación está en el mismo campamento, acéptala si tienes tiempo."}, [29]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [30]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [31]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [32]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [33]={hint="Sir S. J. Erlgadin de la Expedición de Nesingwary, quiere que mates 10 panteras."}, [34]={hint="Hemet Nesingwary quiere que mates 10 raptores de Tuercespina."}, [35]={hint="Ajeck Rouack de la Expedición de Nesingwary, quiere que mates 10 tigres de Tuercespina mayores."}, [36]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [37]={npc="Sir S. J. Erlgadin", tgt="Sir S. J. Erlgadin"}, [38]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [39]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [40]={npc="Hemet Decautela", tgt="Hemet Decautela"}, [41]={npc="Hemet Decautela", tgt="Hemet Decautela"}, [42]={npc="Sargento Yohwa", tgt="Sargento Yohwa"}, [43]={npc="Sargento Yohwa", tgt="Sargento Yohwa"}, [44]={npc="Cabo Kaleb", tgt="Cabo Kaleb"}, [45]={text="Sigue el camino de Vega de Tuercespina todo el rato al sur hasta Bahía del Botín y mantente lejos del campamento de la Horda al pasar cerca de Grom'gol.", tag="Aún no tienes esta ruta de vuelo. Ve a pie la primera vez."}, [46]={npc="Krazek", tgt="Krazek"}, [47]={npc="Krazek", tgt="Krazek"}, [48]={npc="Barón Revilgaz", tgt="Barón Revilgaz"}, [49]={npc="Barón Revilgaz", tgt="Barón Rev