    ["03-27"] = {steps={[1]={npc="Jennea Cannon", tgt="Jennea Cannon", tag="Puedes comprar ya en la casa de subastas (o pedir a un alter que te lo envíe) 1 × Jade (para Objetos de poder, más adelante en el Marjal Revolcafango).", desc="Entrégala a Tabetha en el Marjal Revolcafango."}, [3]={npc="Elling Trias", tgt="Elling Trias"}, [4]={npc="Elling Trias", tgt="Elling Trias"}, [5]={npc="Dashel Puñopiedra", tgt="Dashel Puñopiedra"}, [6]={npc="Dashel Puñopiedra", tgt="Dashel Puñopiedra"}, [7]={hint="Derrota a Dashel Puñopiedra en Ventormenta."}, [8]={npc="Dashel Puñopiedra", tgt="Dashel Puñopiedra"}, [9]={npc="Dashel Puñopiedra", tgt="Dashel Puñopiedra"}, [10]={npc="Elling Trias", tgt="Elling Trias"}, [11]={npc="Elling Trias", tgt="Elling Trias"}, [12]={text="Ve al Distrito de los Enanos de Ventormenta y toma el Tranvía Subterráneo a Forjaz."}, [13]={npc="Gran mampostero Marmolez", tgt="Gran mampostero Marmolez"}, [14]={npc="Gran mampostero Marmolez", tgt="Gran mampostero Marmolez"}, [15]={npc="Rey Magni Barbabronce", tgt="Rey Magni Barbabronce"}, [16]={npc="Gerrig Agarrahueso", tgt="Gerrig Agarrahueso", tag="Opcional", desc="Entrégala solo si recogiste Libro: Los Poderes inferiores en Costa Oscura."}, [17]={npc="Alto Expedicionario Magellas", tgt="Alto Expedicionario Magellas"}, [18]={npc="Prospector Pico Tormenta", tgt="Prospector Pico Tormenta"}, [19]={npc="Prospector Pico Tormenta", tgt="Prospector Pico Tormenta"}, [20]={npc="Prospector Pico Tormenta", tgt="Prospector Pico Tormenta"}, [21]={npc="Prospector Pico Tormenta", tgt="Prospector Pico Tormenta"}, [22]={npc="Llago Llavenegra", tgt="Llago Llavenegra"}, [23]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Vuela de Forjaz a Bahía del Botín (con escala en Ventormenta) y toma el barco a Trinquete."}, [24]={npc="Strahad Farsan", tgt="Strahad Farsan"}, [25]={npc="Krom Brazorrecio", tgt="Krom Brazorrecio", desc="Toma el barco de Trinquete a Bahía del Botín y vuela a Forjaz."}, [26]={npc="Krom Brazorrecio", tgt="Krom Brazorrecio"}, [27]={hint="Lleva el tomo mohoso y el manuscrito maltrecho a Krom Brazorrecio a Forjaz.", desc="Vuela de Forjaz a Costasur y, a la vuelta, de vuelta a Forjaz."}, [28]={npc="Krom Brazorrecio", tgt="Krom Brazorrecio"}, [29]={npc="Krom Brazorrecio", tgt="Krom Brazorrecio"}, [30]={hint="Lleva el tomo restaurado y 3 varas de mediación a Strahad Farsan a Trinquete.", desc="Vuela de Forjaz a Puerto de Menethil para la parte de Los Humedales."}, [31]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Toma el barco del muelle sur de Puerto de Menethil a Theramore, descubre su punto de vuelo y vuela a Trinquete. O vuela de Puerto de Menethil a Bahía del Botín (con escalas en Forjaz y Ventormenta) y toma el barco desde allí."}, [32]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Invoca y derrota al manáfago en el círculo cerca de Strahad Farsan."}, [33]={hint="Mediante el Libro del Conciliábulo invoca y subyuga a un manáfago y luego devuélvele el Libro del Conciliábulo a Strahad Farsan en Trinquete.", desc="Invoca y derrota al manáfago en el círculo cerca de Strahad Farsan."}, [34]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Invoca y derrota al manáfago en el círculo cerca de Strahad Farsan."}, [35]={text="Desde Trinquete sigue el camino de Los Baldíos hacia el norte, pasa El Cruce y continúa hacia el norte hasta entrar en Vallefresno; luego sigue el camino de Vallefresno hacia el oeste hasta Astranaar (34.41, 47.99).", desc="El Cruce y el Puesto del Hachazo son bases de la Horda; rodéalos. Si tienes Theramore en tu mapa de vuelos, puedes volar directamente a Astranaar (con escala en Theramore y Auberdine)."}, [36]={npc="Klockmort Palmalicate", tgt="Klockmort Palmalicate"}, [37]={npc="Eldrun Rompetormentas", tgt="Eldrun Rompetormentas", desc="Llamada del aire: busca a Veyric Thunderhame en las Tierras Altas de Arathi."}, [38]={to="Menethil Harbor", toA="{a:150}"}, [39]={npc="Mikhail", tgt="Mikhail"}, [40]={npc="Mikhail", tgt="Mikhail"}, [41]={hint="Vence a Tapoke Jahn antes de que escape y vuelve a ver a Mikhail en Menethil."}, [42]={npc="Mikhail", tgt="Mikhail"}, [43]={npc="Tapoke Slim Jahn", tgt="Tapoke Slim Jahn"}, [44]={npc="Mikhail", tgt="Mikhail"}, [45]={npc="Mikhail", tgt="Mikhail"}, [46]={npc="Vincent Hyal", tgt="Vincent Hyal", desc="En la misma posada; lleva la carta a Theramore."}, [47]={to="Auberdine", from="Menethil Harbor", fromA="{a:150}", desc="Este barco hace escala en Costasur. Baja en Auberdine."}}},
    ["03-28"] = {steps={[1]={to="Astranaar", toA="{a:415}"}, [2]={npc="Centinela Melyria Sombrigélida", tgt="Centinela Melyria Sombrigélida"}, [3]={npc="Illiyana", tgt="Illiyana"}, [4]={npc="Pelturas Lunablanca", tgt="Pelturas Lunablanca"}, [5]={text="Rodea por el norte y entra en el valle desde aquí."}, [6]={hint="Ve a La Vega del Aullido y estudia el Libro de Mel'Thandris, vuelve entonces junto a la Centinela Melyria Sombrigélida en el Santuario de Aessina.", desc="Entra en la cueva para coger el libro. Es fácil atraer de más, y es más difícil si está el raro."}, [7]={hint="Recupera una piedra lunar caída del Oráculo Sombramatorral y llévasela a Pelturas en Astranaar."}, [8]={text="Vuelve a la carretera principal del norte y entra en el valle por este desvío."}, [9]={hint="Libera las almas de los altonatos atrapadas en la Senda de la Noche y en Satyrnaar y vuelve junto a Delgren el Purificador en la Atalaya de Maestra."}, [10]={npc="Anilia", tgt="Anilia"}, [11]={npc="Anilia", tgt="Anilia"}, [12]={hint="Mata a Geltharis y llévale la Rama de Cenarius a Illiyana en el Santuario de Aessina."}, [13]={npc="Kayneth Ventoleve", tgt="Kayneth Ventoleve"}, [14]={npc="Maseara Lunaotoñal", tgt="Maseara Lunaotoñal"}, [15]={hint="Maseara Lunaotoñal quiere que busques al oeste de Canción del Bosque, entre los demonios de Satyrnaar, y que cuentes cualquier indicio del paradero de su marido, Kurothel."}, [16]={npc="Maseara Lunaotoñal", tgt="Maseara Lunaotoñal"}, [17]={nodeA="{a:3137}", node="Talrendis Point", desc="Desde Canción del Bosque sigue el camino hacia el este hasta entrar en Azshara; el campamento está justo al lado de la entrada."}, [18]={to="Astranaar", toA="{a:415}"}, [19]={npc="Pelturas Lunablanca", tgt="Pelturas Lunablanca"}, [20]={npc="Centinela Melyria Sombrigélida", tgt="Centinela Melyria Sombrigélida"}, [21]={npc="Centinela Melyria Sombrigélida", tgt="Centinela Melyria Sombrigélida", tag="Opcional"}, [22]={npc="Illiyana", tgt="Illiyana"}, [23]={npc="Delgren el Purificador", tgt="Delgren el Purificador"}}},
    ["03-29"] = {grind={[1]={mob="Observador Gapo Salino", note="El extremo sur de El Desierto de Sal; enemigos normales, en la misma zona que los basiliscos de Un bache en la carretera."}, [2]={mob="Vitropiel Gapo Salino", note="Están mezclados con los observadores; son más numerosos y de nivel algo más bajo."}}, steps={[1]={to="Rut'theran Village", toA="{a:702}", tag="Opcional", desc="Poca experiencia en el tramo de Darnassus. Omítelo si tienes prisa."}, [2]={text="Cruza el portal de Aldea Rut'theran hasta Darnassus.", tag="Opcional"}, [3]={npc="Thyn'tel Tejespada", tgt="Thyn'tel Tejespada", tag="Opcional"}, [4]={npc="Thyn'tel Tejespada", tgt="Thyn'tel Tejespada", tag="Opcional"}, [5]={hint="Busca en diario de Velinde en su cofre y llévaselo, junto con la llave, a Thyn'tel Tejespada a Darnassus.", tag="Opcional"}, [6]={npc="Thyn'tel Tejespada", tgt="Thyn'tel Tejespada", tag="Opcional"}, [7]={npc="Thyn'tel Tejespada", tgt="Thyn'tel Tejespada", tag="Opcional"}, [8]={text="Cruza el portal de Darnassus de vuelta a Aldea Rut'theran.", tag="Opcional"}, [9]={text="Si hiciste las misiones opcionales de Darnassus, vuela de Aldea Rut'theran a Trinquete (con escalas en Auberdine y Punta Talrendis); si las saltaste, vuela desde Astranaar (con escala en Punta Talrendis). Sigue el camino principal hacia el sur, rodea el Campamento Taurajo y baja a Las Mil Agujas por el Gran Elevador. Usa la Empalizada de Mor'shan solo si no has descubierto ninguno de los dos puntos."}, [10]={text="Baja hasta el fondo en el Gran Elevador."}, [11]={nodeA="{a:489}", node="Thalanaar"}, [12]={npc="Wizzle Pernolatón", tgt="Wizzle Pernolatón"}, [13]={npc="Wizzle Pernolatón", tgt="Wizzle Pernolatón"}, [14]={npc="Fizzle Pernolatón", tgt="Fizzle Pernolatón"}, [15]={npc="Kravel Karbarbán", tgt="Kravel Karbarbán"}, [16]={npc="Kravel Karbarbán", tgt="Kravel Karbarbán"}, [17]={npc="Kravel Karbarbán", tgt="Kravel Karbarbán"}, [18]={npc="Pozík", tgt="Pozík"}, [19]={npc="Maestro rastreador Zherin", tgt="Maestro rastreador Zherin"}, [20]={hint="Consigue 10 huesos huecos de buitre para Pozzik en El Desierto de Sal."}, [21]={hint="Mata a 10 basiliscos Gapo Salino, 10 pielcristales Gapo Salino y 6 observadores Gapo Salino en El Desierto de Sal."}, [22]={hint="Llévale 9 caparazones de tortuga endurecidos a Wizzle Pernolatón, que está en El Desierto de Sal."}, [23]={hint="Llévale 30 piezas de coche cohete a Kravel Karbarbán, que está en El Desierto de Sal."}, [24]={hint="Llévale 6 glándulas de veneno de escórpidos salados a Wizzle Pernolatón, que está en El Desierto de Sal."}, [25]={npc="Pozík", tgt="Pozík"}, [26]={npc="Maestro rastreador Zherin", tgt="Maestro rastreador Zherin"}, [27]={npc="Wizzle Pernolatón", tgt="Wizzle Pernolatón"}, [28]={npc="Fizzle Pernolatón", tgt="Fizzle Pernolatón"}, [29]={npc="Kravel Karbarbán", tgt="Kravel Karbarbán"}, [30]={desc="Si aún no eres nivel 35 antes de irte de El Desierto de Sal, sube hasta el 35 matando observadores Gapo Salino y vitropieles Gapo Salino al sur del circuito."}, [31]={text="Desde El Desierto de Sal, sigue el camino al sur hasta Tanaris, abre el punto de vuelo de Gadgetzan y luego usa la piedra de hogar.", tag="Aún no tienes esta ruta de vuelo. Ve a pie la primera vez."}, [32]={nodeA="{a:976}", node="Gadgetzan"}, [33]={}}},
    ["03-30"] = {name="Tierras Altas de Arathi", grind={[1]={mob="Kóbold Mostacho Seco", note="Los alrededores de la entrada del Cañón Mostacho Seco; enemigos normales, justo al lado de donde terminas La princesa secuestrada."}, [2]={mob="Cavador Mostacho Seco", note="Junto al cristal, al fondo del cañón; su nivel es más adecuado."}, [3]={mob="Tosco Puño de Roca", note="Los ogros de los alrededores de la Sala Puño de Roca; te pillan de paso cuando vas a por la varita."}, [4]={mob="Cazadora de las Sombras Secacorteza", note="El Poblado Secacorteza, al sureste; son los mismos trols que los de Valer su peso en oro."}}, steps={[1]={to="Refuge Pointe", toA="{a:320}", desc="Si no tienes Refugio de la Zaga, vuela a Puerto de Menethil, sigue el camino al noreste por Los Humedales, cruza el Puente Thandol hasta las Tierras Altas de Arathi y sigue la carretera hasta Refugio de la Zaga."}, [2]={npc="Capitán Nials", tgt="Capitán Nials"}, [3]={npc="Tabla de Se busca", npcObj=true, tag="Grupo recomendado, Opcional"}, [4]={npc="Tabla de Se busca", npcObj=true, tag="Grupo recomendado, Opcional", desc="Otto y Cresta de Halcón son élites de nivel 38 y 40."}, [5]={npc="Skuerto", tgt="Skuerto"}, [6]={npc="Aprendiz Kryten", tgt="Aprendiz Kryten"}, [7]={npc="Fragmentos de Myzrael", npcObj=true}, [8]={hint="Recolecta 12 motas de Myzrael y llévalas a los fragmentos iridiscentes en el Cañón Mostacho Seco."}, [9]={npc="Fragmentos iridiscentes", npcObj=true}, [10]={desc="Sube hasta unos tres cuartos del nivel 36; mata Kóbolds Mostacho Seco y Cavadores Mostacho Seco aquí mismo, en el Cañón Mostacho Seco."}, [11]={npc="Fragmentos iridiscentes", npcObj=true, desc="La Piedra de Vínculo Oriental está de camino al oeste, cógela primero; la Piedra de Vínculo Exterior, cógela de camino al Refugio de la Zaga."}, [12]={npc="Quae", tgt="Quae"}, [13]={npc="Quae", tgt="Quae"}, [14]={hint="Encuentra a la mensajera Renegada y lleva su cartera sellada a Quae cerca de la Granja Go'shek.", desc="El Mensajero Renegado patrulla por el camino de los alrededores de la Granja Go'shek; mátalo en cuanto lo veas y coge la carpeta sellada."}, [15]={hint="Encuentra 10 colmillos Secacorteza, 4 bolsas de medicina Secacorteza y una navaja de cazador de las Sombras para el aprendiz Kryten en el Refugio de la Zaga.", desc="Cuidado con el Mensajero Renegado que patrulla."}, [16]={npc="Aprendiz Kryten", tgt="Aprendiz Kryten"}, [17]={npc="Capitán Nials", tgt="Capitán Nials", desc="Entrega a Demar Brant en el Castillo de Farholde, en Clarofluvial; irás allí en la próxima parada."}, [18]={npc="Skuerto", tgt="Skuerto"}, [19]={desc="Si aún no eres nivel 37 antes de enfrentarte a Kor'gresh Ira Helada (nivel 39), mata Toscos Puño de Roca fuera de la Sala Puño de Roca o ve al Poblado Secacorteza, al este, y mata Trols Secacorteza hasta el 37."}, [20]={hint="Encuentra la varita de evocación de Trelane y llévasela a Skuerto en el Refugio de la Zaga."}, [21]={npc="Quae", tgt="Quae"}, [22]={npc="Quae", tgt="Quae"}, [23]={npc="Kinelory", tgt="Kinelory"}, [24]={npc="Kinelory", tgt="Kinelory"}, [25]={hint="Protege a Kinelory hasta que haya regresado con Quae.", desc="Misión de escolta; sigue a Kinelory. Habrá emboscadas por el camino."}, [26]={npc="Quae", tgt="Quae"}, [27]={npc="Quae", tgt="Quae"}, [28]={npc="Skuerto", tgt="Skuerto"}, [29]={npc="Skuerto", tgt="Skuerto", tag="Grupo recomendado, Opcional"}, [30]={hint="Reúne la llave ardiente, la llave del emblema y la llave tronadora de la Piedra de Vínculo Occidental, la Piedra de Vínculo Oriental y la Piedra de Vínculo Exterior."}, [31]={hint="Mata a 10 bandoleros de la Hermandad y 6 mercenarios de la Hermandad."}, [32]={npc="Capitán Nials", tgt="Capitán Nials"}, [33]={npc="Capitán Nials", tgt="Capitán Nials", tag="Grupo recomendado, Opcional"}, [34]={npc="Piedra de Vínculo Interior", npcObj=true}, [35]={hint="Llévale la cabeza de Marez al capitán Nials en el Refugio de la Zaga.", tag="Grupo recomendado, Opcional"}, [36]={hint="Llévale la cabeza de Otto y la de Cresta de Halcón al capitán Nials en el Refugio de la Zaga.", tag="Grupo recomendado, Opcional"}, [37]={hint="Llévale las insignias de Stromgarde al capitán Nials en el Refugio de la Zaga.", tag="Grupo recomendado, Opcional"}, [38]={hint="Encuentra un ágata azur y llévasela al aprendiz Kryten en el Refugio de la Zaga.", tag="Grupo recomendado, Opcional"}, [39]={npc="Capitán Nials", tgt="Capitán Nials", tag="Grupo recomendado, Opcional"}, [40]={npc="Capitán Nials", tgt="Capitán Nials", tag="Grupo recomendado, Opcional"}, [41]={npc="Capitán Nials", tgt="Capitán Nials", tag="Grupo recomendado, Opcional"}, [42]={npc="Aprendiz Kryten", tgt="Aprendiz Kryten", tag="Grupo recomendado, Opcional"}, [43]={npc="Aprendiz Kryten", tgt="Aprendiz Kryten"}, [44]={npc="Skuerto", tgt="Skuerto"}, [45]={npc="Skuerto", tgt="Skuerto"}, [46]={hint="Encuentra la filacteria de Trelane, el orbe de Trelane y el ágata ámbar de Trelane, y llévaselo todo a Skuerto en el Refugio de la Zaga.", tag="Hazlo cuando te pille de paso"}, [47]={npc="Skuerto", tgt="Skuerto"}, [48]={npc="Skuerto", tgt="Skuerto"}, [49]={hint="Roba un uniforme de la Hermandad en la Mansión Redilnorte e infíltrate en el Castillo de Stromgarde.", desc="Roba un uniforme de la Hermandad en la Mansión Redilnorte, en las Tierras Altas de Arathi."}, [50]={npc="Baúl de la Hermandad", npcObj=true}, [51]={npc="Baúl de la Hermandad", npcObj=true}, [52]={hint="Mientras te haces pasar por un miembro de la Hermandad, encuentra a alguien dentro del Castillo de Stromgarde que esté al corriente del acuerdo secreto."}, [53]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [54]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [55]={hint="Encuentra algo en el Castillo de Stromgarde para convencer a Anastasia de que te revele los detalles del acuerdo secreto."}, [56]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [57]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [58]={hint="Frustra el trato secreto y toma el objeto de la Hermandad. Después, entrégaselo a Myrokos Silenforma en la Mansión Ravenholdt."}, [59]={npc="Myrokos Silenforma", tgt="Myrokos Silenforma"}, [60]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame"}, [61]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame", tag="Grupo recomendado, Opcional", desc="Hay que hacer Horado Rajacieno (la mazmorra del sur de Los Baldíos); hazla cuando consigas grupo; sáltate también la continuación, Tormenta, tierra y fuego."}, [62]={hint="Botín de: Charlga Filonavaja", tag="Grupo recomendado, Opcional"}, [63]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame", tag="Grupo recomendado, Opcional", desc="A Veyric Thunderhame también lo encontrarás en Forjaz (47.10, 13.79)."}, [64]={npc="Veyric Thunderhame", tgt="Veyric Thunderhame", tag="Opcional", desc="Los cuatro tipos de tótem retorcido los sueltan los enemigos de Marjal Revolcafango, las Tierras Inhóspitas, el Pantano de las Penas y Desolace; ve consiguiéndolos por el camino en las próximas paradas; al final, entrégala a Veyric Thunderhame en Forjaz."}, [65]={to="Southshore", toA="{a:271}"}, [66]={npc="Phin Odelic", tgt="Phin Odelic"}, [67]={npc="Magistrado Henry Maleb", tgt="Magistrado Henry Maleb"}, [68]={desc="Si tu piedra de hogar está en reutilización, vuela de Costasur a Forjaz y toma el Tranvía Subterráneo de vuelta a Ventormenta."}}},
    ["05-d8"] = {name="Monasterio Escarlata", entrance="Claros de Tirisfal 82.60, 33.80", pickup="Acepta las misiones de la mazmorra al pasar por Los Humedales (2.ª visita); así no tendrás que volver antes de entrar.", pickupS={{"Acepta las misiones de la mazmorra al pasar por Los Humedales (2.ª visita); así no tendrás que volver antes de entrar"}}, steps={[1]={npc="Bibliotecaria Mae Palipolvo", tgt="Bibliotecaria Mae Palipolvo"}, [2]={to="Southshore", toA="{a:271}", desc="Harás escala en Forjaz."}, [3]={npc="Raleigh el Devoto", tgt="Raleigh el Devoto", tag="Opcional"}, [4]={npc="Raleigh el Devoto", tgt="Raleigh el Devoto", tag="Opcional, Grupo recomendado"}, [5]={npc="Magus Olvek", tgt="Magus Olvek", tag="Opcional"}, [6]={text="Desde Trabalomas, ve al oeste al Bosque de Argénteos y sigue la carretera principal hacia el norte hasta Tirisfal. Rodea los guardias de El Sepulcro, Entrañas y Brill y sigue al Monasterio Escarlata al noreste."}, [7]={text="Entrada: Monasterio Escarlata"}, [8]={hint="Coge Mitología de los Titanes en el monasterio y llévaselo a la bibliotecaria Mae Palipolvo a Forjaz.", desc="Ubicación: Estantería en las últimas salas de la biblioteca.", spot="Estantería en las últimas salas de la biblioteca."}, [9]={hint="Recupera el libro \"La magia perdida de los maestros de runas\" para el Monasterio Escarlata.", tag="Opcional"}, [10]={hint="Mata a la alta inquisidora Melenablanca, al Comandante Escarlata Mograine, a Herod, el Campeón Escarlata y al domador de jaurías Loksey. A continuación, preséntate ante Raleigh el Devoto, en Costasur.", tag="Opcional", desc="Derrota a Loksey en la biblioteca, a Herod en la armería y a Mograine y Melenablanca en la catedral. Puedes completar las alas en visitas distintas."}, [11]={npc="Magus Olvek", tgt="Magus Olvek", tag="Opcional"}, [12]={npc="Raleigh el Devoto", tgt="Raleigh el Devoto", tag="Opcional, Solo con los materiales listos"}, [13]={npc="Bibliotecaria Mae Palipolvo", tgt="Bibliotecaria Mae Palipolvo", tag="Opcional", desc="Regresa por Tirisfal y el Bosque de Argénteos hasta Costasur. Vuela a Forjaz si tienes la ruta. Si no, toma el barco al Puerto de Menethil, sigue el camino de montaña al sur de Los Humedales hasta Loch Modan y cruza el túnel hacia Dun Morogh para llegar a Forjaz. Si tienes la piedra de hogar lista y vinculada a Ventormenta, puedes volver allí y tomar el Tranvía Subterráneo."}}},
    ["03-31"] = {tips={{k="提醒", text="Rog'mar, en el centro del mapa, es una ciudad de la Horda; no te acerques.", s={{"Rog'mar, en el centro del mapa, es una ciudad de la Horda; no te acerques"}}}}, steps={[1]={to="Lakeshire", toA="{a:69}", tag="Antes de ir a Clarofluvial, puedes comprar en la casa de subastas (o pedir a un alter que te lo envíe) 8 × Piedra de afilar sólida (para La hoja más afilada).", desc="El Castillo de Farholde aún no tiene punto de vuelo, así que la primera vez ve al este por el camino desde Villa del Lago hasta la entrada occidental de Clarofluvial."}, [2]={npc="Dorin Filosón", tgt="Dorin Filosón", tag="Opcional, Grupo recomendado"}, [3]={text="Tras la entrada al este de las Montañas Crestagrana están las Colinas Erizadas; los gnolls de nivel 36-38 de la entrada golpean fuerte.", tag="Aún no tienes esta ruta de vuelo. Ve a pie la primera vez."}, [4]={npc="Explorador Bolain", tgt="Explorador Bolain"}, [5]={npc="Cedric Dalton", tgt="Cedric Dalton"}, [6]={npc="Cedric Dalton", tgt="Cedric Dalton"}, [7]={npc="Cedric Dalton", tgt="Cedric Dalton"}, [8]={npc="Cedric Dalton", tgt="Cedric Dalton", tag="Opcional, Grupo recomendado", desc="Snargl es un élite de nivel 40; si no puedes con él, sáltatelo."}, [9]={npc="Curly", tgt="Curly"}, [10]={npc="Halligan Turner", tgt="Halligan Turner"}, [11]={npc="Halligan Turner", tgt="Halligan Turner"}, [12]={npc="Hurley", tgt="Hurley"}, [13]={npc="Hurley", tgt="Hurley"}, [14]={hint="Ve con Hurley a salvar a Curly.", desc="Sigue a Hurley para rescatar a Curly."}, [15]={hint="Mata a 8 místicos de Crestagrana, 8 tramperos de Crestagrana y 6 toscos de Crestagrana para Cedric Dalton en la Guardia Sureña."}, [16]={hint="Recupera 8 hojas serradas en los campamentos de gnolls de las Colinas Erizadas y llévaselas a Halligan Turner en el aserradero.", desc="Las hojas de sierra están esparcidas por el suelo en el campamento gnoll."}, [17]={hint="Busca a Snargl en las Colinas Erizadas, mátalo y lleva su hocico a Cedric Dalton, en la Guardia Sureña.", tag="Opcional, Grupo recomendado", desc="Snargl es un élite de nivel 40; si no puedes con él, sáltatelo."}, [18]={npc="Halligan Turner", tgt="Halligan Turner"}, [19]={npc="Halligan Turner", tgt="Halligan Turner"}, [20]={npc="Eleanor Holmsby", tgt="Eleanor Holmsby"}, [21]={npc="Robbie Holmsby", tgt="Robbie Holmsby"}, [22]={npc="Vigía Fredericks", tgt="Vigía Fredericks"}, [23]={npc="Cedric Dalton", tgt="Cedric Dalton"}, [24]={npc="Cedric Dalton", tgt="Cedric Dalton", tag="Opcional"}, [25]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [26]={hint="Mata a 8 oráculos y guerreros Aletalodo a lo largo del río, cerca de la Hacienda Wheeler."}, [27]={hint="Consigue 4 caparazones de centollo gigante, 4 trozos de estiércol fresco y 8 cabezas de múrloc Aletalodo para Halligan Turner.", desc="Mata las cabezas de múrloc Mudfin junto con los diablillos de agua dulce y luego ve al norte a matar cangrejos de río gigantes y recoger Fertilizante fresco."}, [28]={hint="Encuentra el sombrero de Robbie en el río, cerca de los múrlocs.", desc="Busca el sombrero en el campamento de múrlocs Mudfin."}, [29]={nodeA="{a:16724}", node="Farholde Keep"}, [30]={npc="Demar Brant", tgt="Demar Brant"}, [31]={npc="Demar Brant", tgt="Demar Brant"}, [32]={npc="Demar Brant", tgt="Demar Brant"}, [33]={npc="Demar Brant", tgt="Demar Brant"}, [34]={npc="Ashe Salámbar", tgt="Ashe Salámbar"}, [35]={npc="Ashe Salámbar", tgt="Ashe Salámbar"}, [36]={npc="Ember Filosusurro", tgt="Ember Filosusurro"}, [37]={npc="Hermana Rowland", tgt="Hermana Rowland"}, [38]={npc="Bertrand Frente Recia", tgt="Bertrand Frente Recia"}, [39]={npc="Cassandra Wheeler", tgt="Cassandra Wheeler"}, [40]={hint="Mata a 5 murciumbríos cacareadores en la Catedral de Farholde para la hermana Rowland."}, [41]={npc="Hermana Rowland", tgt="Hermana Rowland"}, [42]={npc="Hermana Rowland", tgt="Hermana Rowland", tag="Opcional, Solo con los materiales listos", desc="Requiere 5 velas sagradas, que venden los vendedores de componentes. Si no las tienes, sáltate esta misión y la siguiente."}, [43]={npc="Hermana Rowland", tgt="Hermana Rowland", tag="Opcional"}, [44]={npc="Hermana Rowland", tgt="Hermana Rowland"}, [45]={hint="Coloca 3 velas memoriales en el cementerio de la capilla en nombre de la hermana Rowland, en el Castillo de Farholde.", desc="La tumba está junto a la capilla de Farholde."}, [46]={npc="Hermana Rowland", tgt="Hermana Rowland"}, [47]={hint="Recoge 3 fardos de heno para Ember en el Campo de Entrenamiento.", desc="Las balas de heno están en los campos cerca de Farholde."}, [48]={npc="Ember Filosusurro", tgt="Ember Filosusurro"}, [49]={npc="Ember Filosusurro", tgt="Ember Filosusurro", tag="Opcional, Solo con los materiales listos", desc="Necesita 8 × Piedra de afilar sólida. Cómpralas en la casa de subastas o pídeselas a un herrero. Sáltala si no los llevas encima."}, [50]={npc="Ember Filosusurro", tgt="Ember Filosusurro", tag="Opcional"}, [51]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [52]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [53]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [54]={hint="Busca pistas del paradero de los caballos por los alrededores de los establos de la Hacienda Wheeler.", desc="Busca pruebas alrededor de los establos de la granja."}, [55]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [56]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [57]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [58]={hint="Mata al coyote apodado Pelajehollín y llévale su pelambre a Benjy Wheeler."}, [59]={hint="Encuentra a uno de los caballos que huyeron de la Hacienda Wheeler tras el ataque de los coyotes y dale el pienso.", desc="El caballo perdido está cerca de la granja."}, [60]={npc="Caballo perdido", tgt="Caballo perdido"}, [61]={npc="Caballo perdido", tgt="Caballo perdido"}, [62]={hint="Devuelve el caballo perdido a la Hacienda Wheeler.", desc="Lleva el caballo extraviado de vuelta a la granja."}, [63]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [64]={npc="Benjy Wheeler", tgt="Benjy Wheeler"}, [65]={npc="Robbie Holmsby", tgt="Robbie Holmsby"}, [66]={npc="Halligan Turner", tgt="Halligan Turner"}, [67]={npc="Halligan Turner", tgt="Halligan Turner"}, [68]={npc="Halligan Turner", tgt="Halligan Turner"}, [69]={hint="Planta 5 pimpollos alrededor del aserradero con el equipo de brote de árbol de Halligan Turner."}, [70]={npc="Halligan Turner", tgt="Halligan Turner"}, [71]={hint="Encuentra el cajón del supervisor y devuélveselo a Bertrand Frente Recia en el Castillo de Farholde.", desc="El cajón del capataz está en el aserradero de Turner."}, [72]={npc="Granjero Elbrim", tgt="Granjero Elbrim"}, [73]={npc="Fuzzle", tgt="Fuzzle"}, [74]={hint="Derrota a 8 asaltantes Crepusculares, 8 sombramánticos Crepusculares y 8 neófitos Crepusculares en Clarosol para Demar Brant."}, [75]={hint="Recupera 5 recuerdos de los granjeros robados por los asaltantes Crepusculares y colócalos en las tumbas al oeste de la Granja de Elbrim.", desc="Mata a los Asaltantes Crepusculares para conseguir los recuerdos y colócalos en las tumbas al oeste de la Granja de Elbrim."}, [76]={hint="Recupera 25 talismanes Crepusculares de los sombramánticos y neófitos Crepusculares de Clarosol para entregárselos a Ashe Salámbar en el Castillo de Farholde."}, [77]={hint="Reúne 5 páginas Crepusculares en Clarosol para entregárselas a Ashe Salámbar en el Castillo de Farholde.", desc="Las páginas del Crepúsculo están esparcidas por Clarosol."}, [78]={npc="Registro de Mariscal de campo", npcObj=true, tag="Solo si cae, Opcional", desc="Los Crepusculares sueltan el registro de Mariscal de campo; haz clic derecho en él en tu mochila para aceptar la misión."}, [79]={hint="Lleva 20 dedos óseos Crepusculares a Fuzzle.", desc="Los dedos óseos Crepusculares salen de los mismos Crepusculares que para Salvar Clarosol."}, [80]={npc="Fuzzle", tgt="Fuzzle"}, [81]={npc="Fuzzle", tgt="Fuzzle", desc="Sigue a Fuzzle mientras huye. Al final se vuelve contra ti con 2 gnolls; derrótalos y luego abre el tesoro."}, 