, [102]={npc="Vigía Cornelius", tgt="Vigía Cornelius"}, [103]={hint="Llévale un pico de zancaalta intacto al vigía Cornelius en la Avanzada de Terral."}, [104]={hint="Recoge 8 pieles de león preciadas para el vigía Terral."}, [105]={hint="Mata 12 cazadores furtivos de Rog'mar para el vigía Cornelius.", desc="Los furtivos están al sur de Rog'mar; no te acerques a Rog'mar, que es una ciudad de la Horda."}, [106]={npc="Vigía Cornelius", tgt="Vigía Cornelius"}, [107]={npc="Vigía Cornelius", tgt="Vigía Cornelius"}, [108]={npc="Vigía Cornelius", tgt="Vigía Cornelius"}, [109]={npc="Vigía Cornelius", tgt="Vigía Cornelius"}, [110]={npc="Vigía Cornelius", tgt="Vigía Cornelius", tag="Opcional, Grupo recomendado", desc="Ombassa es un élite de nivel 41."}, [111]={hint="Usa la llamada del zancaalta para atraer al líder de la manada de leones. Mata a la bestia y llévale su piel al vigía Cornelius en la Avanzada de Terral.", tag="Opcional, Grupo recomendado", desc="Ombassa es un élite de nivel 41."}, [112]={npc="Vigía Cornelius", tgt="Vigía Cornelius", tag="Opcional, Grupo recomendado", desc="Ombassa es un élite de nivel 41."}, [113]={text="Vuelve hacia el sur, al Castillo de Farholde."}, [114]={npc="Ashe Salámbar", tgt="Ashe Salámbar"}, [115]={npc="Ashe Salámbar", tgt="Ashe Salámbar"}, [116]={npc="Ashe Salámbar", tgt="Ashe Salámbar", desc="Primero tienes que derrotar a Chogg'Zac."}, [117]={npc="Demar Brant", tgt="Demar Brant"}, [118]={npc="Demar Brant", tgt="Demar Brant"}, [119]={npc="Bertrand Frente Recia", tgt="Bertrand Frente Recia"}}},
