    ["03-36"] = {steps={[1]={to="Darkshire", toA="{a:42}"}, [2]={npc="Maestro de vigilantes Sorigal", tgt="Maestro de vigilantes Sorigal"}, [3]={text="Desde Villa Oscura, ve al este por el Paso de la Muerte hasta el Pantano de las Penas."}, [4]={npc="Vigilante Biggs", tgt="Vigilante Biggs"}, [5]={hint="Llévale 10 pizcas de polvo de sueño a Krazek a Bahía del Botín. El polvo de sueño se obtiene de las crías de dragón que habitan en el Pantano de las Penas."}, [6]={hint="Mata a 8 crocoliscos Denteserra jóvenes, 10 girapenas y 10 jaguares del pantano, y después ve a ver al vigilante Biggs al Pantano de las Penas."}, [7]={npc="Vigilante Biggs", tgt="Vigilante Biggs"}, [8]={npc="Vigilante Biggs", tgt="Vigilante Biggs"}, [9]={npc="Cayada de Noboru", npcObj=true, tag="Opcional", desc="Haz clic derecho en Cayada de Noboru en tu bolsa para empezar la misión. Mata a Noboru el Garrote para conseguir una cayada gris y haz clic derecho en ella para empezar la misión."}, [10]={npc="Magtoor", tgt="Magtoor", tag="Opcional"}, [11]={npc="Magtoor", tgt="Magtoor"}, [12]={hint="Llévale 6 cristales draenetistas a Magtoor que está en El Malecón del Pantano de las Penas."}, [13]={hint="Encuentra el cofre de la caravana en Retiro Fangoso, consigue los componentes de zahorí y llévaselos al vigilante Biggs."}, [14]={npc="Galen Bonguarda", tgt="Galen Bonguarda"}, [15]={hint="Pon a salvo a Galen, y después encuentra su campamento en el Pantano de las Penas y abre su caja fuerte.", tag="Escolta", desc="Sigue a Galen fuera del Retiro Fangoso (el campamento de los Perdidos); los enemigos del camino lo atacarán, así que protégelo. Tras la escolta, ve a su campamento y abre la caja fuerte."}, [16]={npc="Caja fuerte de Galen", npcObj=true}, [17]={npc="Magtoor", tgt="Magtoor"}, [18]={npc="Vigilante Biggs", tgt="Vigilante Biggs"}, [19]={npc="Vigilante Biggs", tgt="Vigilante Biggs"}, [20]={hint="Llévale 8 piezas de madera a la deriva desecada al vigilante Biggs en el Pantano de las Penas."}, [21]={hint="Brohann Barriliga, en Ventormenta, quiere que busques el Templo de Atal'Hakkar.", desc="Se completa al acercarte al Templo Sumergido."}, [22]={npc="Vigilante Biggs", tgt="Vigilante Biggs"}, [23]={npc="Vigilante Biggs", tgt="Vigilante Biggs"}, [24]={text="Desde el sur del Pantano de las Penas, entra en Las Tierras Devastadas y sigue el camino al sur hasta el Castillo de Nethergarde.", tag="Aún no tienes esta ruta de vuelo. Ve a pie la primera vez."}, [25]={npc="Intendente Lungertz", tgt="Intendente Lungertz"}, [26]={nodeA="{a:1438}", node="Nethergarde Keep"}}},
    ["03-37"] = {tips={{k="提醒", text="Rog'mar, en el centro del mapa, es una ciudad de la Horda; no te acerques.", s={{"Rog'mar, en el centro del mapa, es una ciudad de la Horda; no te acerques"}}}}, steps={[1]={to="Farholde Keep", toA="{a:16724}", tag="Antes de ir a Clarofluvial, puedes comprar en la casa de subastas (o pedir a un alter que te lo envíe) 20 × Tela de paño mágico (para Vendas para heridas).", desc="Harás escala en Villa Oscura y Villa del Lago."}, [2]={npc="Demar Brant", tgt="Demar Brant"}, [3]={npc="Demar Brant", tgt="Demar Brant"}, [4]={npc="Demar Brant", tgt="Demar Brant", desc="Primero tienes que entregar el El registro de Mariscal de campo que se activa al soltarse, o no podrás aceptarla."}, [5]={npc="Ashe Salámbar", tgt="Ashe Salámbar"}, [6]={npc="Bertrand Frente Recia", tgt="Bertrand Frente Recia"}, [7]={npc="Hermano Lowley", tgt="Hermano Lowley", tag="Opcional, Solo con los materiales listos", desc="Necesita 20 × Tela de paño mágico. Se puede comprar en la casa de subastas. Sáltala si no los llevas encima."}, [8]={npc="Hermano Lowley", tgt="Hermano Lowley", tag="Opcional"}, [9]={npc="Hermano Lowley", tgt="Hermano Lowley"}, [10]={hint="Venda las heridas de 3 soldados para el hermano Lowley.", desc="Los soldados heridos están justo al lado del Hermano Lowley."}, [11]={npc="Hermano Lowley", tgt="Hermano Lowley"}, [12]={npc="Hermano Lowley", tgt="Hermano Lowley"}, [13]={npc="Hermana Rowland", tgt="Hermana Rowland"}, [14]={npc="Tessa Albabrillante", tgt="Tessa Albabrillante"}, [15]={hint="Recoge 6 manzanas frescas para Tessa Albabrillante en el Castillo de Farholde.", desc="Las manzanas frescas están bajo los manzanos cerca de Farholde."}, [16]={npc="Tessa Albabrillante", tgt="Tessa Albabrillante"}, [17]={npc="Tessa Albabrillante", tgt="Tessa Albabrillante"}, [18]={hint="Reúne 3 pelambres de coyote para Tessa Albabrillante en el Castillo de Farholde."}, [19]={npc="Tessa Albabrillante", tgt="Tessa Albabrillante"}, [20]={npc="Tessa Albabrillante", tgt="Tessa Albabrillante"}, [21]={npc="Vigía Cornelius", tgt="Vigía Cornelius"}, [22]={text="Desde la Avanzada de Terral ve al oeste, pasando al sur de Clarosol, hasta el sargento Riftan, frente a Sudario Crepuscular. Al pasar por el Aserradero de Turner, recoge la madera."}, [23]={hint="Recoge 10 montones de madera en el Aserradero de Turner para Bertrand Frente Recia en el Castillo de Farholde.", desc="Los troncos están en el aserradero de Turner."}, [24]={npc="Sargento Riftan", tgt="Sargento Riftan"}, [25]={npc="Sargento Riftan", tgt="Sargento Riftan"}, [26]={npc="Sargento Riftan", tgt="Sargento Riftan"}, [27]={npc="Sargento Riftan", tgt="Sargento Riftan"}, [28]={hint="Invoca un Siervo Crepuscular de un conducto en el Sudario Crepuscular y atrápalo con la piedra de alma de Salámbar.", desc="En el conducto de Sudario Crepuscular, invoca a un Siervo Crepuscular y captúralo con una piedra de alma."}, [29]={npc="Alguacil Ryan", tgt="Alguacil Ryan"}, [30]={npc="Alguacil Ryan", tgt="Alguacil Ryan"}, [31]={hint="Rescata a 5 exploradores de Farholde dentro del Sudario Crepuscular para el sargento Riftan.", desc="Los exploradores están encerrados por todo el Sudario Crepuscular."}, [32]={hint="Derrota a 8 fanáticos Crepusculares, 8 corruptores Crepusculares y 8 campeones Crepusculares dentro del Sudario Crepuscular para el sargento Riftan."}, [33]={hint="Derrota a 5 mineros ogros y a 5 subyugadores Crepusculares en la cueva cercana al Sudario Crepuscular para el sargento Riftan."}, [34]={npc="Sargento Riftan", tgt="Sargento Riftan"}, [35]={npc="Sargento Riftan", tgt="Sargento Riftan"}, [36]={npc="Sargento Riftan", tgt="Sargento Riftan"}, [37]={npc="Sargento Riftan", tgt="Sargento Riftan", tag="Opcional, Grupo recomendado", desc="Señor supremo Kilgar es un élite de nivel 46."}, [38]={hint="Derrota al señor supremo Kilgar en el Sudario Crepuscular y llévale su cabeza al sargento Riftan.", tag="Opcional, Grupo recomendado", desc="Señor supremo Kilgar es un élite de nivel 46."