    ["04-44"] = {grind={[1]={mob="Lechubestia salvaje", note="El bosque del centro de Tierras del Interior; hay muchos enemigos y son los mismos que los de las plumas de lechúcico."}, [2]={mob="Acechador melenargenta", note="Las manadas de lobos que hay más al este; están dispersos y puedes matarlos de uno en uno."}}, steps={[1]={to="Southshore", toA="{a:271}", desc="Si no tienes Costasur, vuela a Puerto de Menethil, toma el barco a Auberdine en el muelle norte y baja en Costasur."}, [2]={npc="Raleigh el Devoto", tgt="Raleigh el Devoto", tag="Opcional"}, [3]={npc="Raleigh el Devoto", tgt="Raleigh el Devoto", tag="Opcional, Grupo recomendado", desc="Derrota a Loksey en la biblioteca, a Herod en la armería y a Mograine y Melenablanca en la catedral. Puedes completar las alas en visitas distintas."}, [4]={npc="Raleigh el Devoto", tgt="Raleigh el Devoto", tag="Opcional, Solo con los materiales listos"}, [5]={text="Toma el sendero de montaña hacia el noreste para entrar en Tierras del Interior."}, [6]={npc="Falstad Martillo Salvaje", tgt="Falstad Martillo Salvaje"}, [7]={nodeA="{a:348}", node="Aerie Peak"}, [8]={npc="Falstad Martillo Salvaje", tgt="Falstad Martillo Salvaje"}, [9]={npc="Maestro de grifos Garracha", tgt="Maestro de grifos Garracha"}, [10]={npc="Maestro de grifos Garracha", tgt="Maestro de grifos Garracha"}, [11]={npc="Maestro de grifos Garracha", tgt="Maestro de grifos Garracha"}, [12]={npc="Fraggar Mantrueno", tgt="Fraggar Mantrueno"}, [13]={npc="Fraggar Mantrueno", tgt="Fraggar Mantrueno"}, [14]={text="Vincula tu piedra de hogar en la posada del Pico Nidal (13.80, 41.60).", bindA="{a:348}"}, [15]={npc="Rapsodio Machacacanillas", tgt="Rapsodio Machacacanillas", desc="De camino a las lechubestias; para la continuación hay que llevar licor, no la aceptes."}, [16]={hint="Recoge 15 plumas de lechúcico de las Tierras del Interior y llévaselas a Erelas Cieloámbar a la Aldea Rut'theran."}, [17]={hint="Mira en las jaulas de los poblados Secacorteza y vuelve a ver