    ["04-57"] = {danger={[1]="Ghansurok (quimera élite de nivel 61) patrulla desde los hibiscos contaminados hasta el taller de Kaylaena (hacia x55-62,5, y61,5-72,2); mira dónde está al golpear los arbustos y al volver al taller.", [2]="Celastrus el Amargo (élite de nivel 57) merodea por los hibiscos contaminados; ten cuidado al golpear los arbustos.", [3]="El montón de huesos invoca un cieno élite de nivel 58; no hagas clic una segunda vez sin grupo."}, grind={[1]={note="La parte norte de la Cicatriz Sangrevil; todas las misiones de Felflick se pelean aquí."}}, supply={[1]={}}, steps={[1]={text="Desde Ranshalla ve al sur hasta entrar en la Garganta Negro Rumor (59.82, 74.25), sigue el desfiladero hacia el oeste hasta el final y entrarás en el Monte Hyjal. Hay gigantes de escarcha élite en la entrada del desfiladero y demonios élite dentro; pégate al camino y no te detengas.", tag="Aún no tienes esta ruta de vuelo. Ve a pie la primera vez."}, [2]={hint="Sigue las indicaciones de Donova Cubilnevado y vuelve a informarle.", desc="Se completa al atravesar el desfiladero hacia el Monte Hyjal; no hace falta dar ningún rodeo. Cuenta en cuanto el registro de misiones la muestre como completada."}, [3]={text="Entra en el Monte Hyjal por la esquina sureste y sigue el camino al oeste."}, [4]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [5]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [6]={npc="Loose Cog", npcObj=true, desc="Un engranaje en el suelo junto al camino; haz clic derecho para recogerlo y aceptar la misión."}, [7]={npc="Ketharas", tgt="Ketharas", tag="Opcional", desc="Entrégala solo si la aceptaste antes en Frondavil."}, [8]={npc="Ketharas", tgt="Ketharas"}, [9]={npc="Ketharas", tgt="Ketharas"}, [10]={npc="Ketharas", tgt="Ketharas"}, [11]={npc="Ketharas", tgt="Ketharas"}, [12]={npc="Ketharas", tgt="Ketharas"}, [13]={hint="Rescue 12 Hyjal Owl Eggs and bring them to Ketharas."}, [14]={hint="Collect 10 Untainted Seeds for Ketharas."}, [15]={npc="Ketharas", tgt="Ketharas"}, [16]={npc="Ketharas", tgt="Ketharas"}, [17]={npc="Ketharas", tgt="Ketharas"}, [18]={npc="Ketharas", tgt="Ketharas"}, [19]={hint="Botín de: Hyjal Stag, Predatory Hyjal Stag"}, [20]={hint="Plant the Enchanted Seeds near the Ruined Ballista, the Ruined Catapult, and the Ruined Flying Machine.", desc="Los restos de la ballesta, la catapulta y la máquina voladora cuentan cada uno como un objetivo, y hay que plantar los tres. Búscalos en la ladera fuera de la Cueva del Ermitaño."}, [21]={npc="Ketharas", tgt="Ketharas"}, [22]={npc="Ketharas", tgt="Ketharas"}, [23]={npc="Ketharas", tgt="Ketharas"}, [24]={hint="Bury the remains at Ketharas' shrine."}, [25]={npc="Ketharas", tgt="Ketharas"}, [26]={npc="Ketharas", tgt="Ketharas"}, [27]={nodeA="{a:16853}", node="Tainted Foothills", desc="Sigue el camino al oeste; el punto de vuelo está junto al puesto de los ancestros."}, [28]={npc="Fraxinus", tgt="Fraxinus"}, [29]={npc="Hyacinth", tgt="Hyacinth"}, [30]={npc="Hyacinth", tgt="Hyacinth"}, [31]={npc="Thylaen", tgt="Thylaen", tag="Grupo recomendado, Opcional", desc="El objetivo es una élite de nivel 57; si no puedes con él en solitario, no la aceptes."}, [32]={hint="Collect 6 samples of Untainted Soil from around the foothills of Mount Hyjal."}, [33]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Cuando vayas después a Vista Eterna, busca a Nami para las piezas."}, [36]={hint="Matar: Tainted Shrubbery", desc="Los mismos hibiscos sueltan también las hojas que detienen la hemorragia; golpéalos para ambas misiones a la vez. Entrégalo en el taller cuando lleves la caja."}, [37]={hint="Botín de: Tainted Shrubbery"}, [38]={hint="Botín de: Celastrus the Bitter", tag="Grupo recomendado, Opcional"}, [39]={npc="Thylaen", tgt="Thylaen", tag="Grupo recomendado, Opcional"}, [40]={npc="Hyacinth", tgt="Hyacinth"}, [41]={npc="Hyacinth", tgt="Hyacinth"}, [42]={npc="Hyacinth", tgt="Hyacinth"}, [43]={hint="Matar: Fraxinus"}, [44]={npc="Fraxinus", tgt="Fraxinus"}, [45]={npc="Fraxinus", tgt="Fraxinus", tag="Grupo recomendado, Opcional", desc="El objetivo, Sunderbark, es un ancestro élite de nivel 56; hazla cuando tengas grupo; si no tienes grupo, sáltatela y la entrega posterior se omitirá automáticamente."}, [46]={npc="Fraxinus", tgt="Fraxinus"}, [47]={npc="Curious Crow", tgt="Curious Crow"}, [48]={npc="Curious Crow", tgt="Curious Crow"}, [49]={npc="Curious Crow", tgt="Curious Crow"}, [50]={npc="Felflick", tgt="Felflick"}, [51]={npc="Felflick", tgt="Felflick"}, [52]={hint="Matar: Ashen Acolyte", desc="Las notas las sueltan los mismos acólitos; pelea contra ellos para ambas misiones."}, [53]={hint="Botín de: Ashen Acolyte"}, [54]={npc="Felflick", tgt="Felflick"}, [55]={npc="Felflick", tgt="Felflick"}, [56]={hint="Gather 8 Fel-Slime Crystals and 1 Pristine Fel-Slime Crystal."}, [57]={npc="Curious Crow", tgt="Curious Crow"}, [58]={npc="Curious Crow", tgt="Curious Crow"}, [59]={npc="Curious Crow", tgt="Curious Crow"}, [60]={hint="Botín de: Babosa nociva"}, [61]={hint="Collect 10 Prickly Pinecones under healthy trees."}, [62]={npc="Curious Crow", tgt="Curious Crow"}, [63]={npc="Curious Crow", tgt="Curious Crow"}, [64]={npc="Felflick", tgt="Felflick"}, [65]={npc="Felflick", tgt="Felflick"}, [66]={npc="Felflick", tgt="Felflick"}, [67]={hint="Botín de: Tyaeha Darkoath, Dazka Shadowsleep, Frezzlie Popwhiz"}, [68]={hint="Matar: Brashann Grimdark"}, [69]={npc="Felflick", tgt="Felflick"}, [70]={npc="Felflick", tgt="Felflick"}, [71]={npc="Felflick", tgt="Felflick"}, [72]={npc="Bone Pile", npcObj=true, desc="Arroja los huesos de brujo al montón de huesos junto al charco de cieno."}, [73]={npc="Bone Pile", npcObj=true, tag="Grupo recomendado, Opcional", desc="Invoca una babosa élite de nivel 58; si no tienes grupo, sáltate Amalgamated Marrow y sus continuaciones."}, [74]={hint="Matar: Awakened Fel Ash Slime", tag="Grupo recomendado, Opcional"}, [75]={npc="Velician", tgt="Velician"}, [76]={npc="Felflick", tgt="Felflick", tag="Grupo recomendado, Opcional"}, [77]={npc="Felflick", tgt="Felflick"}, [78]={npc="Curious Crow", tgt="Curious Crow"}, [79]={npc="Curious Crow", tgt="Curious Crow"}, [80]={npc="Curious Crow", tgt="Curious Crow"}, [81]={npc="Curious Crow", tgt="Curious Crow"}, [82]={hint="Use the pinecones to destroy the Ashen Reign workstations."}, [83]={npc="Curious Crow", tgt="Curious Crow"}, [84]={npc="Curious Crow", tgt="Curious Crow", desc="Entrégalo en Saucoancestro, al oeste, en el siguiente punto."}, [85]={hint="Hunt down and destroy the corrupted ancient Sunderbark, then plant a seed in his remains.", tag="Grupo recomendado, Opcional", desc="En el camino de vuelta al este, hacia la Cueva del Ermitaño."}, [86]={npc="Ketharas", tgt="Ketharas"}, [87]={npc="Ketharas", tgt="Ketharas"}, [88]={npc="Fraxinus", tgt="Fraxinus", tag="Grupo recomendado, Opcional"}, [89]={to="Everlook", toA="{a:2255}"}, [90]={npc="Nami", tgt="Nami", desc="La caja siguiente tiene límite de tiempo; acéptala cuando vuelvas de Claro de la Luna."}, [91]={npc="Jaron Tallapiedras", tgt="Jaron Tallapiedras", desc="Desde Vista Eterna sigue el camino al oeste un trecho hasta Aldea Estrella Fugaz."}, [92]={text="Cabalga al suroeste por el camino desde Aldea Estrella Fugaz hasta las aguas termales y busca a Donova."}, [93]={npc="Donova Cubilnevado", tgt="Donova Cubilnevado"}, [94]={to="Claro de la Luna", desc="Cabalga de vuelta de las aguas termales al punto de vuelo de Vista Eterna y vuela (el punto de vuelo de Claro de la Luna se abrió en {s:04-49}). Si tu reputación con los Fauces de Madera ya es neutral, cabalga al norte desde las aguas termales hasta la entrada de Bastión Fauces de Madera (27.70, 34.50); cruzar la cueva hasta la salida a Claro de la Luna queda más cerca; si no abriste el punto de vuelo de Claro de la Luna, toma también esta ruta y ábrelo primero al llegar (48.10, 67.34); por debajo de neutral te atacarán. Los druidas pueden usar Teletransporte: Claro de la Luna directamente; al llegar, ve al punto de vuelo normal (48.10, 67.34) y ábrelo para poder volver volando. Si no abriste el punto de vuelo de Claro de la Luna, toma también esta ruta y ábrelo primero al llegar (48.10, 67.34). Por debajo de neutral te atacarán. Los druidas pueden usar Teletransporte: Claro de la Luna directamente; al llegar, ve al punto de vuelo normal (48.10, 67.34) y ábrelo para poder volver volando."}, [95]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [96]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [97]={npc="Orokai", tgt="Orokai"}, [98]={npc="Orokai", tgt="Orokai"}, [99]={hint="Speak with Orokai when you are ready to see what he learned from the Faintly Glowing Branch."}, [100]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [101]={npc="Dendrite Rafagaestelar", tgt="Dendrite Rafagaestelar"}, [102]={to="Everlook", toA="{a:2255}", desc="Despega desde el punto de vuelo normal de Claro de la Luna (48.10, 67.34) y baja en Vista Eterna para recoger la caja."}, [103]={npc="Nami", tgt="Nami", desc="Las pilas de la caja dejan de funcionar tras unas dos horas, así que entrégala directamente a Kaylaena desde el punto de vuelo."}, [104]={to="Tainted Foothills", toA="{a:16853}", desc="Desde el punto de vuelo cabalga directamente al norte hasta el taller de Kaylaena y entrega primero la caja."}}},
    ["04-58"] = {danger={[1]="Ghansurok (quimera élite de nivel 61) patrulla al este del Santuario de Aviana; ten cuidado al pelear contra arpías."}, supply={[1]={}, [2]={}}, steps={[1]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Desde el punto de vuelo cabalga directamente al norte hasta el taller y entrega primero la caja."}, [2]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [3]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Los materiales están en los restos del campamento de la Horda en Dae'gun, al norte; recógelos cuando pases más tarde."}, [4]={npc="Ketharas", tgt="Ketharas", desc="Cabalga al sureste desde el taller de vuelta a la Cueva del Ermitaño."}, [5]={npc="Ketharas", tgt="Ketharas"}, [6]={npc="Ketharas", tgt="Ketharas"}, [7]={npc="Skylord Omnuron", tgt="Skylord Omnuron", desc="Cabalga al noroeste desde la Cueva del Ermitaño hasta el Santuario de Aviana."}, [8]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [9]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [10]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [11]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [12]={hint="Botín de: Wormwing Harpy, Wormwing Windwitch, Wormwing Ambusher"}, [13]={hint="Collect 8 Tarnished Highfeather Bangles from Wormwing Harpy nests."}, [14]={hint="Find the Jewel of the Horizon in the Wormwing harpy nests on Mount Hyjal and bring it to Ketharas."}, [15]={hint="Botín de: Zarrat Wormwing"}, [16]={npc="Corrupted Growth", npcObj=true, desc="Haz clic derecho en la masa corrupta del árbol para aceptar la misión."}, [17]={hint="Usar/recoger: Corrupted Growth"}, [18]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [19]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [20]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [21]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [22]={npc="Curious Crow", tgt="Curious Crow"}, [23]={npc="Curious Crow", tgt="Curious Crow", desc="Solo puedes hacerla en 