"}, [72]={npc="Elder Pinespeaker", tgt="Elder Pinespeaker", tag="Opcional", desc="Entrégala solo cuando tu reputación haya llegado a amistoso. Si no tienes suficiente, guárdala por ahora."}, [73]={npc="Eluneth", tgt="Eluneth", desc="Ve al norte."}, [74]={npc="Veteran of the Third War", tgt="Veteran of the Third War"}, [75]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [76]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [77]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [78]={npc="Mirt", tgt="Mirt"}, [79]={npc="Hnaz Blunderflame", tgt="Hnaz Blunderflame", desc="Junto a la posada de Saucoancestro; los nidos de búho están en el valle del sur, para recogerlos de paso cuando vuelvas con Eluneth."}, [80]={hint="Matar: Escaped Sheep"}, [81]={npc="Mirt", tgt="Mirt"}, [82]={npc="Embroidered Scabbard", npcObj=true, desc="El mirador al oeste de Saucoancestro."}, [83]={npc="Embroidered Scabbard", npcObj=true}, [84]={hint="Use the Embroidered Scabbard to speak with the war veteran and hear his story at the overlook in Elderwild."}, [85]={npc="Veteran of the Third War", tgt="Veteran of the Third War"}, [86]={npc="Unmarked Grave", npcObj=true, desc="Junto al camino hacia el este, haz clic derecho en la tumba sin nombre para aceptar la misión."}, [87]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre"}, [88]={hint="Fill Galvinquam Leafsyre's drinking gourd at the waterfall ahead.", desc="Llena agua con la calabaza vacía que da la misión en la cascada de delante, no junto a Galvinquam."}, [89]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre"}, [90]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre", desc="Lleva el equipaje a la Cima de la Eternidad."}, [91]={npc="Lisbael Highfeather", tgt="Lisbael Highfeather", desc="Entrégalo después en el Santuario de Aviana."}, [92]={hint="Touch the Crow Effigy on the bridge overlooking the Cradle of Tranquility to call the Wild God, Jereman."}, [93]={npc="Jereman", tgt="Jereman"}, [94]={npc="Jereman", tgt="Jereman"}, 