    [4130] = {n="Lectura psicométrica", d="Ve al Bastión Plumaluna y habla con Ginro Mechogar."},
    [4131] = {n="Los gnolls Zarpaleña", d="Busca el rastro del mensajero o sus pertenencias en los campamentos de los gnoll Zarpaleña del sur de Feralas."},
    [4135] = {n="Las Entrañas Retorcidas", d="Ahora que has descubierto el rastro de Raschal, adéntrate en Las Entrañas Retorcidas y encuéntrale... o encuentra lo que quede de él. Según la nota, debes dirigirte al sur de los campamentos de los Zarpaleña."},
    [4141] = {n="Muigin y Larion", d="Recoge 15 pétalos de sangre y ve a ver a Muigin.", tgo={{"Azotador Sangrepétalo", "Despellejador Sangrepétalo", "Trillador Sangrepétalo", "Trampero Sangrepétalo"}}},
    [4142] = {n="Visita a Gregan", d="Llévale un pétalo de sangre a Gregan Vomitabrebaje de Feralas."},
    [4161] = {n="La receta de los Kaldorei", d="Recoge 7 patas de araña pequeña para Zarrin, que está en Dolanaar.", tgo={{"Araña del bosque", "Araña minera", "Madre Colmillo", "Rondador del risco", "Rondadora maderera", "Rondador del bosque", "Nocturácnida sañosa", "Acechamusgo"}}},
    [4182] = {n="La amenaza de los dragonantes", d="Mata 15 cachorrillos negros, 10 dragauros negros, 4 vermis negros y 1 draco negro. Vuelve junto a Helendis Rivacuerno cuando hayas acabado la tarea.", tgo={{"Estirpe negra"}, {"Dragauro negro"}, {"Draco negro"}, {"Vermis negro"}}},
    [4183] = {n="Los verdaderos maestros", d="Viaja a Villa del Lago y entrégale la carta de Helendis Rivacuerno al magistrado Salomón."},
    [4184] = {n="Los verdaderos maestros", d="Ve a Ventormenta para entregar la petición de ayuda de Solomon al Gran Señor Bolvar Fordragon.\nVive en el Castillo de Ventormenta."},
    [4185] = {n="Los verdaderos maestros", d="Habla con el Alto Señor Bolvar Fordragon después de hablar con Lady Katrana Prestor.", tgo={{"Lady Katrana Prestor"}}},
    [4186] = {n="Los verdaderos maestros", d="Lleva el decreto de Bolvar al magistrado Salomón en la Villa del Lago."},
    [4223] = {n="Los verdaderos maestros", d="Habla con el alguacil Maxwell en Las Estepas Ardientes."},
    [4224] = {n="Los verdaderos maestros", d="Habla con John Andrajoso para averiguar el destino del alguacil Windsor y vuelve junto al alguacil Maxwell cuando hayas completado la tarea.\nRecuerdas que el alguacil Maxwell comentó algo sobre buscarlo en una cueva hacia el norte.", tgo={{"John Andrajoso"}}},
    [4241] = {n="El alguacil Windsor", d="Viaja a la Montaña Roca Negra al noroeste y adéntrate en las Profundidades de Roca Negra. Averigua qué le ha ocurrido al alguacil Windsor.\nRecuerdas que John Andrajoso había comentado que se habían llevado a una cárcel a Windsor."},
    [4243] = {n="Buscando a Memo 01", d="Encuentra a Memo 01 en el Cráter de Un'Goro."},
    [4244] = {n="Buscando a Memo 01", d="Encuentra una envoltura de mitril y reúnete de nuevo con Memo 01 en el Cráter de Un'Goro.", tgo={{"Clonk", "Unidad machacadora Lobo Gélido", "Unidad machacadora Pico Tormenta", "7:XT"}}},
    [4245] = {n="Buscando a Memo 01", d="Lleva a Memo 01 de vuelta con Karna Tipirrem al Cráter de Un'Goro."},
