    [4283] = {n="¡CINCUENTA! ¡SÍ!", d="Oralius quiere 50 medallones Roca Negra. Con toda probabilidad encontrarás estos medallones en los orcos de Las Estepas Ardientes.", tgo={{"Soldado Roca Negra", "Hechicero Roca Negra", "Destripador Roca Negra", "Brujo Roca Negra", "Maestro de batalla Roca Negra", "Huargo Roca Negra", "Lupo Brasal", "Huargo brasal babeante"}}},
