    [4421] = {n="La corrupción de los Fuego de Jade", d="Mata a 11 jurapenas Fuego de Jade, 9 acechasombras Fuego de Jade, 9 pícaros Fuego de Jade y a Xavathras. Vuelve con Eridan Vientoazul a Frondavil cuando hayas completado la misión.", tgo={{"Jurapenas Fuego de Jade"}, {"Acechasombras Fuego de Jade"}, {"Pícaro Fuego de Jade"}, {"Xavathras"}}},
    [4441] = {n="Los Ancestros corrompidos", d="Viaja a Darnassus y utiliza el vial de Eridan para recoger agua bendita del Templo de la Luna. Vuelve a Eridan con el vial lleno.", objs={"Templo de la Fuente de la Luna"}},
