    [6388] = {n="Gryth Thurden", d="Lleva los picos honoríficos a Gryth Thurden a Forjaz."},
    [6389] = {n="Una Peste en la Cruzada", d="Libera las termitas de las Tierras de la Peste en la Serrería Crestanorte y luego vuelve con el barril de termitas a las Tierras de la Peste del Oeste y busca a Nathaniel Dumah en el Campamento del Orvallo."},
    [6391] = {n="Vuela a Forjaz", d="Contrata un vuelo en grifo a Forjaz con el maestro de grifos Thorgrum Borrelson para llevar la lista de Brock a Golnir Dedorroca."},
    [6392] = {n="Vuelve con Brock", d="Contrata un vuelo en grifo a Thelsamar con el maestro de grifos Gryth Thurden para llevar los picos honoríficos a Brock Buscapiedras."},
