    [8252] = {n="El coral de las sirenas", d="Reúne 6 corales encantados y llévaselos al archimago Xylem.", tgo={{"Sirena Látigo de Ira"}}},
    [8253] = {n="Destruye a Morphaz", d="Recupera el fragmento arcano de Morphaz y llévaselo al archimago Xylem.", tgo={{"Morphaz"}}},
    [8254] = {n="Ayuda a Cenarion", d="Busca a Ogtinc en Azshara."},
    [8255] = {n="Los trotadores Pezuñamusgo", d="Consigue 4 glándulas de trotadores sanos y llévaselas a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.", tgo={{"Trotador Pezuñamusgo"}}},
    [8256] = {n="El icor de los no-muertos", d="Consigue un icor de los no-muertos para Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath.", tgo={{"Zombi Zanzil", "Cazador Zanzil", "Despellejador esquelético", "Hechicero esquelético", "Terror esquelético", "Ejecutor esquelético", "Señor de la guerra esquelético", "Acólito esquelético"}}},
    [8257] = {n="La sangre de Morphaz", d="Mata a Morphaz en El Templo Sumergido de Atal'Hakkar y lleva su sangre a Greta Pezuñamusgo en Frondavil. Encontrarás la entrada al Templo Sumergido en el Pantano de las Penas.", tgo={{"Morphaz"}}},
    [8365] = {n="¡Sombreros de pirata da babor!", d="La modista Jonti quiere que reúnas 20 sombreros de pirata del Mar del Sur y que se los lleves al Puerto Bonvapor de Tanaris.", tgo={{"Pirata del Mar del Sur", "Filibustero del Mar del Sur", "Portuario del Mar del Sur", "Aventurero del Mar del Sur", "Andre Barbafuego", "Kregg Volcayecto"}}},
