    [8414] = {n="Expulsión de los demonios", d="Recoge 20 piedras de la Plaga del esbirro y entrégaselas al sumo sacerdote Thel'danis en las Tierras de la Peste del Oeste.", tgo={{"Despellejador esquelético", "Hechicero esquelético", "Terror esquelético", "Ejecutor esquelético", "Acólito esquelético", "Necrófago esclavizante", "Necrófago en podredumbre", "Necrófago desalmado"}}},
