    [91753] = {n="Una lección de encantamiento", d="Kitta Vientofuego, en la Torre de Azora, quiere que reúnas 3 de residuo luminoso.\nEste residuo se puede obtener desencantando las efigies de cera rudimentarias que llevan los geománticos kóbold."},
